-- 105 AI phase three reliability fields; forward-only and idempotent.
SET @schema_name=DATABASE();
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set' AND COLUMN_NAME='base_digest'),'ALTER TABLE `fun_ai_change_set` ADD COLUMN `base_digest` char(64) NOT NULL DEFAULT '''' AFTER `digest`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='cleanup_lease_owner'),'ALTER TABLE `fun_ai_task` ADD COLUMN `cleanup_lease_owner` varchar(128) NULL AFTER `cleanup_at`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='status' AND COLUMN_TYPE NOT LIKE '%resume_pending%'),'ALTER TABLE `fun_ai_task` MODIFY COLUMN `status` enum(\'pending\',\'running\',\'resume_pending\',\'succeeded\',\'failed\',\'cancelled\',\'paused\',\'recovery_required\') NOT NULL DEFAULT \'pending\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='sandbox_status' AND COLUMN_TYPE NOT LIKE '%cleaning%'),'ALTER TABLE `fun_ai_task` MODIFY COLUMN `sandbox_status` enum(\'pending\',\'created\',\'running\',\'exported\',\'cleaning\',\'cleaned\',\'failed\') NOT NULL DEFAULT \'pending\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='cleanup_lease_expires_at'),'ALTER TABLE `fun_ai_task` ADD COLUMN `cleanup_lease_expires_at` datetime NULL AFTER `cleanup_lease_owner`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='sandbox_volume'),'ALTER TABLE `fun_ai_task` ADD COLUMN `sandbox_volume` varchar(255) NULL AFTER `container_task_id`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_outbox'),'CREATE TABLE `fun_ai_outbox` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`aggregate_type` varchar(64) NOT NULL,`aggregate_id` bigint unsigned NOT NULL,`event_type` varchar(128) NOT NULL,`idempotency_key` varchar(191) NOT NULL,`payload` json NOT NULL,`status` enum(\'pending\',\'dispatched\',\'failed\') NOT NULL DEFAULT \'pending\',`attempts` int unsigned NOT NULL DEFAULT 0,`available_at` datetime NOT NULL,`last_error` text NULL,`dispatched_at` datetime NULL,`created_at` datetime NOT NULL,`updated_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_outbox_idempotency` (`idempotency_key`),KEY `idx_ai_outbox_dispatch` (`status`,`available_at`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
